    .data-note strong { color: #92400e; }

    /* ── TAKEAWAYS ── */
    .takeaway-list { counter-reset: tk; list-style: none; }
    .takeaway-list li {
      counter-increment: tk;
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 20px 20px 20px 70px;
      position: relative;
      margin-bottom: 14px;
